def load() -> pd.DataFrame:
    import glob
    import os
    import pandas as pd

    pattern = 'data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv'
    paths = sorted(glob.glob(pattern))
    if not paths:
        raise FileNotFoundError(f'No files matched pattern: {pattern}')

    return pd.DataFrame({'path': paths, 'file': [os.path.basename(p) for p in paths]})

def process(msaIdentityTheftFiles) -> pd.DataFrame:
    import pandas as pd

    # Inspect a few representative files (first 3 alphabetically)
    sample_paths = msaIdentityTheftFiles['path'].sort_values().head(3).tolist()
    out = []
    for p in sample_paths:
        try:
            raw = pd.read_csv(p, header=None, nrows=25)
            out.append({'path': p, 'preview': raw.to_csv(sep='\t', index=False, header=False)})
        except Exception as e:
            out.append({'path': p, 'error': str(e)})
    return pd.DataFrame(out)
